def transform_center(grid):
 g=[row[:] for row in grid]; bg=8
 cells=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v!=bg]
 rs=[r for r,c in cells]; r0,r1=min(rs),max(rs); mid=(r0+r1)//2
 colors=sorted({g[r][c] for r,c in cells})
 seam_left=min(c for r,c in cells if r==mid)
 dx=len(g[0])//2-seam_left
 out=[[bg]*len(g[0]) for _ in g]
 for r,c in cells:
  nc=c+dx if r<=mid else c
  out[r][nc]=colors[1] if g[r][c]==colors[0] else colors[0]
 return out
